const response = $input.first().json;
const rawToken = response?.access_token ?? response?.data?.access_token ?? response?.result?.access_token ?? response?.token?.access_token ?? response?.data?.token;
if (!rawToken || !String(rawToken).trim()) {
  throw new Error('Access token tidak ditemukan pada respons Olsera.');
}
const accessToken = String(rawToken).trim().replace(/^Bearer\s+/i, '');
return [{ json: { access_token: accessToken } }];

const token = String($input.first().json.access_token ?? '').trim();
if (!token) throw new Error('Access token Olsera kosong.');
return [{ json: {
  access_token: token,
  business_date: new Date((new Date()).valueOf() - 1000*3600*24),
  revenue_field: 'net_amount',
  record_key_fields: ['id'],
  row_grain: 'order',
  wunpaid: '0',
  amount_basis: 'net_amount-per-order; Olsera default unpaid filter',
  source_scope: 'grandivo-main',
  calculation_version: 'v1',
  per_page: 15,
  source_endpoint: 'https://api-open.olsera.co.id/api/open-api/v1/en/report/salesdetails',
  source_fetched_at: new Date().toISOString(),
} }];

const config = $('Tanggal Bisnis WIB & Konfigurasi').first().json;
const responseItems = $input.all();
if (responseItems.length !== 2) {
  throw new Error('Merge harus menghasilkan tepat 2 respons, diterima ' + responseItems.length + '.');
}

const normalizeDecimal = (value, label) => {
  let raw;
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value)) throw new Error(label + ' berupa number yang tidak aman.');
    raw = String(value);
  } else if (typeof value === 'string') {
    raw = value.trim();
  } else {
    throw new Error(label + ' harus number atau string desimal.');
  }
  const match = /^-?(\d+)(?:\.(\d+))?$/.exec(raw);
  if (!match || match[1].length > 20 || (match[2] ?? '').length > 8) {
    throw new Error(label + ' bukan desimal kanonik: ' + raw);
  }
  return raw;
};

const toScaled = (raw) => {
  const negative = raw.startsWith('-');
  const unsigned = negative ? raw.slice(1) : raw;
  const [whole, fraction = ''] = unsigned.split('.');
  const scaled = BigInt(whole) * 100000000n + BigInt(fraction.padEnd(8, '0'));
  return negative ? -scaled : scaled;
};

const extractPaymentMethod = (row) => {
  const candidate = row.payment_method ?? row.payment_method_name ?? row.pay_method ?? row.payment_type ?? row.payment_type_name ?? row.payment_name ?? row.pay_mode ?? row.payment_mode ?? row.payment_mode_name ?? row.cara_bayar ?? row.metode_pembayaran ?? row.payment_channel ?? (typeof row.payment === 'string' ? row.payment : (row.payment?.name ?? row.payment?.payment_name ?? row.payment?.method ?? row.payment?.payment_type)) ?? (Array.isArray(row.payments) && row.payments.length > 0 ? (row.payments.map((p) => (typeof p === 'string' ? p : (p?.name ?? p?.payment_method ?? p?.payment_name ?? p?.type ?? p?.method))).filter(Boolean).join(', ')) : null) ?? (Array.isArray(row.payment_list) && row.payment_list.length > 0 ? (row.payment_list.map((p) => (typeof p === 'string' ? p : (p?.name ?? p?.payment_method ?? p?.payment_name ?? p?.type ?? p?.method))).filter(Boolean).join(', ')) : null);
  if (candidate === undefined || candidate === null) return '';
  return typeof candidate === 'object' ? JSON.stringify(candidate) : String(candidate).trim();
};

const pages = new Map();
for (const item of responseItems) {
  const statusCode = Number(item.json?.statusCode);
  const body = item.json?.body;
  if (statusCode !== 200 || !body || Number(body.status) !== 200 || Number(body.error) !== 0 || !body.meta) {
    throw new Error('Respons HTTP Olsera gagal atau tidak lengkap.');
  }
  const current = Number(body.meta.current_page);
  const last = Number(body.meta.last_page);
  if (!Number.isInteger(current) || !Number.isInteger(last) || current < 1 || last < current) {
    throw new Error('Metadata pagination Olsera tidak valid: current=' + current + ', last=' + last + '.');
  }
  if (pages.has(current)) {
    throw new Error('Olsera membalas dua request sebagai current_page=' + current + '. Pastikan node Halaman 2 memakai URL literal page=2; PostgreSQL belum ditulis.');
  }
  pages.set(current, body);
}

if (!pages.has(1) || !pages.has(2)) {
  throw new Error('Respons wajib berisi current_page=1 dan current_page=2; diterima: ' + [...pages.keys()].sort().join(', ') + '.');
}
if ([...pages.values()].some((body) => Number(body.meta.last_page) !== 2)) {
  throw new Error('last_page bukan 2. Konfigurasi halaman statis perlu diperbarui sebelum database ditulis.');
}

const rows = [1, 2].flatMap((page) => {
  const data = pages.get(page).data;
  if (!Array.isArray(data)) throw new Error('body.data halaman ' + page + ' bukan array.');
  return data;
});
const expectedTotal = Number(pages.get(1).meta.total);
if (!Number.isInteger(expectedTotal) || rows.length !== expectedTotal) {
  throw new Error('Jumlah order tidak cocok: diterima ' + rows.length + ', meta.total=' + expectedTotal + '.');
}

const keys = new Set();
let rowAmountScaled = 0n;
const normalizedRows = rows.map((row, index) => {
  if (!row || typeof row !== 'object' || Array.isArray(row)) throw new Error('Order indeks ' + index + ' bukan object.');
  const id = String(row.id ?? '').trim();
  if (!id) throw new Error('Order indeks ' + index + ' tidak memiliki id.');
  const recordKey = 'id=' + encodeURIComponent(id);
  if (keys.has(recordKey)) throw new Error('ID order duplikat: ' + id + '.');
  keys.add(recordKey);
  const amount = normalizeDecimal(row.net_amount, 'net_amount order ' + id);
  rowAmountScaled += toScaled(amount);
  return {
    record_key: recordKey,
    order_id: id,
    order_no: String(row.order_no ?? '').trim(),
    source_timestamp_raw: String(row.order_time ?? row.order_date ?? '').trim(),
    status: String(row.status ?? '').trim(),
    payment_status: String(row.is_paid ?? '').trim(),
    payment_method: extractPaymentMethod(row),
    customer_id: String(row.customer_id ?? '').trim(),
    store_id: String(row.store_id ?? '').trim(),
    revenue_amount: amount,
    raw_payload: row,
  };
});

const aggregate = pages.get(1).totaldata?.[0];
if (!aggregate || aggregate.net_amount === undefined || aggregate.net_amount === null) {
  throw new Error('totaldata[0].net_amount tidak tersedia untuk rekonsiliasi.');
}
const aggregateAmount = normalizeDecimal(aggregate.net_amount, 'totaldata.net_amount');
if (rowAmountScaled !== toScaled(aggregateAmount)) {
  throw new Error('Jumlah net_amount order tidak cocok dengan totaldata.net_amount; PostgreSQL belum ditulis.');
}

const sourceMetadata = [1, 2].map((page) => {
  const meta = pages.get(page).meta;
  return {
    requested_page: page,
    current_page: Number(meta.current_page),
    last_page: Number(meta.last_page),
    per_page: Number(meta.per_page),
    from: meta.from,
    to: meta.to,
    total: Number(meta.total),
    http_status_code: 200,
  };
});

return [{ json: {
  source_scope: config.source_scope,
  business_date: config.business_date,
  report_row_count: normalizedRows.length,
  page_count: 2,
  revenue_field: config.revenue_field,
  record_key_fields_json: JSON.stringify(config.record_key_fields),
  row_grain: config.row_grain,
  wunpaid: config.wunpaid,
  amount_basis: config.amount_basis,
  calculation_version: config.calculation_version,
  source_endpoint: config.source_endpoint,
  source_fetched_at: config.source_fetched_at,
  rows_json: JSON.stringify(normalizedRows),
  source_metadata_json: JSON.stringify(sourceMetadata),
  reconciled_net_amount: aggregateAmount,
} }];

const config = $('Tanggal Bisnis WIB & Konfigurasi').first().json;
const responseItems = $input.all();
if (responseItems.length !== 2) {
  throw new Error('Merge harus menghasilkan tepat 2 respons, diterima ' + responseItems.length + '.');
}

const normalizeDecimal = (value, label) => {
  let raw;
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value)) throw new Error(label + ' berupa number yang tidak aman.');
    raw = String(value);
  } else if (typeof value === 'string') {
    raw = value.trim();
  } else {
    throw new Error(label + ' harus number atau string desimal.');
  }
  const match = /^-?(\d+)(?:\.(\d+))?$/.exec(raw);
  if (!match || match[1].length > 20 || (match[2] ?? '').length > 8) {
    throw new Error(label + ' bukan desimal kanonik: ' + raw);
  }
  return raw;
};

const toScaled = (raw) => {
  const negative = raw.startsWith('-');
  const unsigned = negative ? raw.slice(1) : raw;
  const [whole, fraction = ''] = unsigned.split('.');
  const scaled = BigInt(whole) * 100000000n + BigInt(fraction.padEnd(8, '0'));
  return negative ? -scaled : scaled;
};

const extractPaymentMethod = (row) => {
  const candidate = row.payment_method ?? row.payment_method_name ?? row.pay_method ?? row.payment_type ?? row.payment_type_name ?? row.payment_name ?? row.pay_mode ?? row.payment_mode ?? row.payment_mode_name ?? row.cara_bayar ?? row.metode_pembayaran ?? row.payment_channel ?? (typeof row.payment === 'string' ? row.payment : (row.payment?.name ?? row.payment?.payment_name ?? row.payment?.method ?? row.payment?.payment_type)) ?? (Array.isArray(row.payments) && row.payments.length > 0 ? (row.payments.map((p) => (typeof p === 'string' ? p : (p?.name ?? p?.payment_method ?? p?.payment_name ?? p?.type ?? p?.method))).filter(Boolean).join(', ')) : null) ?? (Array.isArray(row.payment_list) && row.payment_list.length > 0 ? (row.payment_list.map((p) => (typeof p === 'string' ? p : (p?.name ?? p?.payment_method ?? p?.payment_name ?? p?.type ?? p?.method))).filter(Boolean).join(', ')) : null);
  if (candidate === undefined || candidate === null) return '';
  return typeof candidate === 'object' ? JSON.stringify(candidate) : String(candidate).trim();
};

const bodies = responseItems.map((item, index) => {
  const statusCode = Number(item.json?.statusCode);
  const body = item.json?.body;
  if (statusCode !== 200 || !body || Number(body.status) !== 200 || Number(body.error) !== 0 || !body.meta || !Array.isArray(body.data)) {
    throw new Error('Respons Olsera ke-' + (index + 1) + ' gagal atau tidak lengkap.');
  }
  return body;
});

const reportedPages = bodies.map((body) => Number(body.meta.current_page));
const reportedTotals = bodies.map((body) => Number(body.meta.total));
if (reportedTotals.some((total) => !Number.isInteger(total) || total < 0) || new Set(reportedTotals).size !== 1) {
  throw new Error('meta.total Olsera tidak valid atau berubah antar-request.');
}
const apiReportedTotal = reportedTotals[0];

const rowsById = new Map();
for (const body of bodies) {
  for (const row of body.data) {
    const id = String(row?.id ?? '').trim();
    if (!id) throw new Error('Ada order Olsera tanpa id.');
    if (rowsById.has(id)) {
      if (JSON.stringify(rowsById.get(id)) !== JSON.stringify(row)) {
        throw new Error('Payload order id=' + id + ' berubah antar-request.');
      }
      continue;
    }
    rowsById.set(id, row);
  }
}
const rows = [...rowsById.values()];
const duplicatePageAnomaly = reportedPages.length === 2 && reportedPages.every((page) => page === 1);
const completePagination = new Set(reportedPages).size === 2 && reportedPages.includes(1) && reportedPages.includes(2);
if (!duplicatePageAnomaly && !completePagination) {
  throw new Error('Kombinasi current_page Olsera tidak dikenali: ' + reportedPages.join(', ') + '.');
}
if (completePagination && rows.length !== apiReportedTotal) {
  throw new Error('Pagination terlihat lengkap tetapi jumlah row ' + rows.length + ' tidak cocok dengan meta.total ' + apiReportedTotal + '.');
}
if (duplicatePageAnomaly && rows.length >= apiReportedTotal) {
  throw new Error('Anomali halaman terdeteksi tetapi jumlah row tidak konsisten.');
}

let rowAmountScaled = 0n;
const normalizedRows = rows.map((row) => {
  const id = String(row.id).trim();
  const amount = normalizeDecimal(row.net_amount, 'net_amount order ' + id);
  rowAmountScaled += toScaled(amount);
  return {
    record_key: 'id=' + encodeURIComponent(id),
    order_id: id,
    order_no: String(row.order_no ?? '').trim(),
    source_timestamp_raw: String(row.order_time ?? row.order_date ?? '').trim(),
    status: String(row.status ?? '').trim(),
    payment_status: String(row.is_paid ?? '').trim(),
    payment_method: extractPaymentMethod(row),
    customer_id: String(row.customer_id ?? '').trim(),
    store_id: String(row.store_id ?? '').trim(),
    revenue_amount: amount,
    raw_payload: row,
  };
});

const aggregates = bodies.map((body) => body.totaldata?.[0]).filter(Boolean);
if (aggregates.length !== 2) throw new Error('totaldata Olsera tidak tersedia pada kedua respons.');
const aggregateAmounts = aggregates.map((aggregate) => normalizeDecimal(aggregate.net_amount, 'totaldata.net_amount'));
if (new Set(aggregateAmounts).size !== 1) throw new Error('totaldata.net_amount berubah antar-request.');
const aggregateAmount = aggregateAmounts[0];
if (rowAmountScaled !== toScaled(aggregateAmount)) {
  throw new Error('Jumlah net_amount detail tidak cocok dengan totaldata.net_amount; PostgreSQL belum ditulis.');
}

const detailComplete = completePagination && rows.length === apiReportedTotal;
const missingDetailRows = apiReportedTotal - rows.length;
const metadata = [{
  detail_complete: detailComplete,
  api_pagination_anomaly: duplicatePageAnomaly ? 'page_2_returned_page_1' : null,
  requested_pages: [1, 2],
  received_current_pages: reportedPages,
  api_reported_total: apiReportedTotal,
  retrieved_unique_rows: rows.length,
  missing_detail_rows: missingDetailRows,
  aggregate_net_amount: aggregateAmount,
  aggregate_reconciled: true,
  per_page: Number(bodies[0].meta.per_page),
  api_last_page: Number(bodies[0].meta.last_page),
  first_response_from: bodies[0].meta.from,
  first_response_to: bodies[0].meta.to,
}];

return [{ json: {
  source_scope: config.source_scope,
  business_date: config.business_date,
  report_row_count: normalizedRows.length,
  page_count: 1,
  revenue_field: config.revenue_field,
  record_key_fields_json: JSON.stringify(config.record_key_fields),
  row_grain: config.row_grain,
  wunpaid: config.wunpaid,
  amount_basis: config.amount_basis + (detailComplete ? '' : '; partial-detail-api-pagination-anomaly'),
  calculation_version: detailComplete ? config.calculation_version : config.calculation_version + '-partial-detail',
  source_endpoint: config.source_endpoint,
  source_fetched_at: config.source_fetched_at,
  rows_json: JSON.stringify(normalizedRows),
  source_metadata_json: JSON.stringify(metadata),
  reconciled_net_amount: aggregateAmount,
  detail_complete: detailComplete,
  missing_detail_rows: missingDetailRows,
  sync_warning: detailComplete ? null : 'Omzet lengkap dan tereksiliasi; detail order tidak lengkap karena page=2 dibalas sebagai page=1 oleh Olsera.',
} }];

const items = $input.all();
const results = items.map((item) => {
  const raw = item.json.result;
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw === 'string') return JSON.parse(raw);
  throw new Error('PostgreSQL tidak mengembalikan hasil sinkronisasi.');
});
const warnings = items
  .filter((item) => item.json.detail_complete === false)
  .map((item) => ({ missing_detail_rows: Number(item.json.missing_detail_rows), message: item.json.sync_warning }));
return [{ json: {
  status: warnings.length ? 'SUCCESS_WITH_WARNING' : 'SUCCESS',
  message: warnings.length
    ? 'Omzet tersimpan dan tereksiliasi, tetapi detail Sales Details tidak lengkap karena anomali pagination Olsera.'
    : 'Snapshot Sales Details lengkap berhasil ditangani PostgreSQL.',
  results,
  warnings,
  synced_at_wib: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }),
} }];
